void splitUint32Id(uint32_t uint32Id, uint16_t &uint16IdUpper, uint16_t &uint16IdLower)
{
        uint16IdLower = (uint32Id & 0x0000ffff);
        uint16IdUpper = (uint32Id & 0xffff0000) >> 16;
}

