                clientHelloMessage->getHandshakeVersion();

                pcpp::SSLCipherSuite::getCipherSuiteByName("TLS_RSA_WITH_NULL_MD5");
                for (int i = 0; i < clientHelloMessage->getCipherSuiteCount(); i++)
                {
                    clientHelloMessage->getCipherSuite(i);
